package lk.ac.sliit.ridelink.ride.infrastructure.configuration;
import org.springframework.context.annotation.*; import org.springframework.http.client.SimpleClientHttpRequestFactory; import org.springframework.web.client.RestClient; import java.time.Duration;
@Configuration public class RestClientConfiguration {private SimpleClientHttpRequestFactory factory(RideProperties p){var f=new SimpleClientHttpRequestFactory();f.setConnectTimeout(Duration.ofMillis(p.connectTimeoutMs()));f.setReadTimeout(Duration.ofMillis(p.readTimeoutMs()));return f;}@Bean RestClient accountRestClient(RideProperties p){return RestClient.builder().baseUrl(p.accountServiceUrl()).requestFactory(factory(p)).build();}@Bean RestClient driverRestClient(RideProperties p){return RestClient.builder().baseUrl(p.driverServiceUrl()).requestFactory(factory(p)).build();}@Bean RestClient fareRestClient(RideProperties p){return RestClient.builder().baseUrl(p.farePaymentServiceUrl()).requestFactory(factory(p)).build();}}
